import React, { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import '../assets/styles/Navbar.css';
import logo from '../assets/images/logo.png';

const Navbar = () => {
  const navigate = useNavigate();
  const [token, setToken] = useState(null);

  useEffect(() => {
    // Check token on mount
    const storedToken = localStorage.getItem('token'); // ✅ match SignIn.jsx
    setToken(storedToken);

    // Listen for login/logout changes across tabs
    const handleStorageChange = () => {
      const updatedToken = localStorage.getItem('token'); // ✅ match SignIn.jsx
      setToken(updatedToken);
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  const handleSignOut = () => {
    localStorage.removeItem('token'); // ✅ match SignIn.jsx
    localStorage.removeItem('user');  // optional: clear user info
    setToken(null);

    // Trigger Navbar update
    window.dispatchEvent(new Event('storage'));

    // Redirect to home or signin
    navigate('/signin');
  };

  return (
    <nav className="navbar">
      <div className="navbar-logo">
        <img src={logo} alt="GP Logo" />
      </div>

      <ul className="navbar-links">
        <li><Link to="/">Home</Link></li>
        <li><Link to="/about">About Me</Link></li>
        <li><Link to="/projects">Projects</Link></li>
        <li><Link to="/education">Education</Link></li>
        <li><Link to="/services">Services</Link></li>
        <li><Link to="/contact">Contact Me</Link></li>

        {!token ? (
          <>
            <li><Link to="/signin">Sign In</Link></li>
            <li><Link to="/signup">Sign Up</Link></li>
          </>
        ) : (
          <li>
            <button className="signout-btn" onClick={handleSignOut}>
              Sign Out
            </button>
          </li>
        )}
      </ul>
    </nav>
  );
};

export default Navbar;
